def count_turns(config):
    turns = 0
    while True:
        k = config.count(1)
        if k == 0:
            break
        config[k-1] = 1 - config[k-1]
        turns += 1
    return turns

def solve_for_n(n):
    total_turns = 0
    for i in range(2**n):
        config = [(i >> j) & 1 for j in range(n)]
        total_turns += count_turns(config)
    return total_turns

for n in range(1, 7):
    total = solve_for_n(n)
    print(f"N={n}, Total={total}, Average={total/(2**n)}")

def get_next_state(config):
    k = config.count(1)
    if k == 0:
        return None
    new_config = list(config)
    new_config[k-1] = 1 - new_config[k-1]
    return tuple(new_config)

def is_finite(n):
    for i in range(2**n):
        config = tuple([(i >> j) & 1 for j in range(n)])
        visited = set()
        current = config
        while current is not None and current not in visited:
            visited.add(current)
            current = get_next_state(current)
        if current is not None:
            return False, config
    return True, None

for n in range(1, 6):
    finite, config = is_finite(n)
    print(f"N={n}, finite={finite}")

